CREATE TABLE "epg_epgsource" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "source_type" varchar(20) NOT NULL, "url" varchar(1000) NULL, "api_key" varchar(255) NULL, "is_active" bool NOT NULL, "file_path" varchar(1024) NULL, "refresh_interval" integer NOT NULL, "refresh_task_id" integer NULL REFERENCES "django_celery_beat_periodictask" ("id") DEFERRABLE INITIALLY DEFERRED, "created_at" datetime NOT NULL, "updated_at" datetime NULL, "status" varchar(20) NOT NULL, "last_message" text NULL, "extracted_file_path" varchar(1024) NULL, "custom_properties" text NULL CHECK ((JSON_VALID("custom_properties") OR "custom_properties" IS NULL)), "priority" integer unsigned NOT NULL CHECK ("priority" >= 0), "programme_index" text NULL CHECK ((JSON_VALID("programme_index") OR "programme_index" IS NULL)))
CREATE INDEX "epg_epgsource_refresh_task_id_56cffd0b" ON "epg_epgsource" ("refresh_task_id")
